#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_channels,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int out_h,
    int out_w
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_y = threadIdx.x;
    int out_x = threadIdx.y;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || 
        out_y >= out_h || out_x >= out_w) return;

    // Shared memory for input tile
    extern __shared__ half shared_input[];

    // Initialize accumulator
    float acc = 0.0f;

    // Loop over input channels and kernel elements
    for (int ch = 0; ch < channels; ch++) {
        for (int kh = 0; kh < kernel_h; kh++) {
            for (int kw = 0; kw < kernel_w; kw++) {
                int input_y = out_y * stride_h - pad_h + kh;
                int input_x = out_x * stride_w - pad_w + kw;

                // Check bounds
                if (input_y >= 0 && input_y < height && 
                    input_x >= 0 && input_x < width) {
                    int input_idx = batch_idx * (channels * height * width) +
                                   ch * (height * width) +
                                   input_y * width + input_x;
                    int weight_idx = out_ch_idx * (channels * kernel_h * kernel_w) +
                                    ch * (kernel_h * kernel_w) +
                                    kh * kernel_w + kw;

                    acc += (float)input[input_idx] * (float)weight[weight_idx];
                }
            }
        }
    }

    // Write result
    int output_idx = batch_idx * (out_channels * out_h * out_w) +
                     out_ch_idx * (out_h * out_w) +
                     out_y * out_w + out_x;
    output[output_idx] = __float2half(acc);
}

// Wrapper function to launch kernel
extern "C" void launch_conv2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_channels,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int out_h,
    int out_w
) {
    dim3 grid(batch_size, out_channels);
    dim3 block(out_h, out_w);
    size_t shared_mem_size = 2 * channels * (height + 2 * pad_h) * (width + 2 * pad_w) * sizeof(half);

    conv2d_kernel<<<grid, block, shared_mem_size>>>(
        input, weight, output, batch_size, channels, height, width, 
        out_channels, kernel_h, kernel_w, stride_h, stride_w, pad_h, pad_w, out_h, out_w
    );
}
"""

# Load the CUDA extension
conv_module = load_inline(
    name="conv2d_cuda",
    cpp_sources=[],
    cuda_sources=[cuda_source],
    functions=["launch_conv2d"],
    verbose=True
)

class ModelNew(torch.nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = torch.nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        # Use our custom CUDA kernel for the convolution
        batch_size, channels, height, width = x.shape

        # Get kernel parameters
        weight = self.conv1.weight.data.contiguous()
        bias = self.conv1.bias.data.contiguous() if self.conv1.bias is not None else None

        # Calculate output dimensions
        out_channels = weight.shape[0]
        kernel_h, kernel_w = weight.shape[2], weight.shape[3]
        stride_h, stride_w = self.conv1.stride
        pad_h, pad_w = self.conv1.padding
        out_h = (height + 2 * pad_h - kernel_h) // stride_h + 1
        out_w = (width + 2 * pad_w - kernel_w) // stride_w + 1

        # Allocate output tensor
        output = torch.empty(batch_size, out_channels, out_h, out_w, dtype=torch.float16, device=x.device)

        # Launch CUDA kernel
        conv_module.launch_conv2d(
            x.contiguous().view(-1).data_ptr(),
            weight.contiguous().view(-1).data_ptr(),
            output.view(-1).data_ptr(),
            batch_size,
            channels,
            height,
            width,
            out_channels,
            kernel_h,
            kernel_w,
            stride_h,
            stride_w,
            pad_h,
            pad_w,
            out_h,
            out_w
        )

        # Add bias if present
        if bias is not None:
            bias_expanded = bias.view(1, -1, 1, 1).expand_as(output)
            output = output + bias_expanded

        return output

